"use client";

import React, { useEffect, useRef, useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";

type PortalState = "idle" | "hover" | "holding" | "complete";

export default function IntroPortal({ onEnter }: { onEnter: () => void }) {
  const [state, setState] = useState<PortalState>("idle");
  const [progress, setProgress] = useState(0);

  const holdStartRef = useRef<number | null>(null);
  const rafRef = useRef<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const HOLD_DURATION = 1800; // 1.8 seconds

  /* ✅ مسارات الصور الصحيحة 100% من فولدر مشروعك */
  const ASSETS = {
    idle: "/images/intro/mizo-state1-off.png",
    hover: "/images/intro/mizo-state2-ready.png",
    active: "/images/intro/mizo-state3-active.png",
  };

  /* --- PRELOAD --- */
  useEffect(() => {
    Object.values(ASSETS).forEach((src) => {
      const img = new Image();
      img.src = src;
    });
  }, []);

  /* --- HOLD ENGINE (SMOOTH RAF) --- */
  const animateHold = useCallback(() => {
    rafRef.current = requestAnimationFrame((now) => {
      if (!holdStartRef.current) return;
      const elapsed = now - holdStartRef.current;
      const pct = Math.min(elapsed / HOLD_DURATION, 1);
      setProgress(pct);

      if (pct >= 1) {
        setState("complete");
        setTimeout(() => {
          if (typeof onEnter === "function") onEnter();
        }, 600);
        return;
      }
      animateHold();
    });
  }, [onEnter]);

  const startHold = (e: React.PointerEvent) => {
    e.preventDefault();
    if (state === "complete") return;
    setState("holding");
    holdStartRef.current = performance.now();
    animateHold();
  };

  const cancelHold = (e: React.PointerEvent) => {
    e.preventDefault();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    holdStartRef.current = null;
    setProgress(0);
    if (state !== "complete") setState("hover");
  };

  /* --- PARALLAX DEPTH --- */
  const handleMove = (e: React.PointerEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = (e.clientX - rect.width / 2) / rect.width;
    const y = (e.clientY - rect.height / 2) / rect.height;
    containerRef.current.style.transform = `translate3d(${x * 8}px, ${y * 8}px, 0)`;
  };

  return (
    <AnimatePresence>
      {state !== "complete" && (
        <motion.div
          ref={containerRef}
          className="fixed inset-0 z-[999999] flex flex-col items-center justify-between bg-black"
          style={{
            background: "radial-gradient(circle at center, #000000 60%, #040404 100%)",
            height: "100dvh", width: "100vw", overflow: "hidden", userSelect: "none", WebkitTapHighlightColor: "transparent"
          }}
          initial={{ opacity: 1 }}
          exit={{ opacity: 0, scale: 1.05, filter: "blur(15px)" }}
          transition={{ duration: 1.2 }}
          onPointerMove={handleMove}
        >
          {/* الحماية الشاملة */}
          <style dangerouslySetInnerHTML={{__html: `
            * { -webkit-tap-highlight-color: transparent !important; -webkit-touch-callout: none !important; user-select: none !important; }
            img { pointer-events: none !important; }
            body { overscroll-behavior: none; }
          `}} />

          {/* 1. الحاوية العلوية للصورة (60% من الشاشة) - تضمن ارتكاز التمثال النصفي بالأسفل */}
          <div
            className="relative w-full flex items-end justify-center cursor-pointer mt-auto"
            style={{ height: "60dvh", maxWidth: "600px" }}
            onPointerEnter={() => state === "idle" && setState("hover")}
            onPointerLeave={() => state !== "complete" && setState("idle")}
            onPointerDown={startHold}
            onPointerUp={cancelHold}
            onPointerCancel={cancelHold}
            onContextMenu={(e) => e.preventDefault()}
          >
            <motion.img src={ASSETS.idle} alt="Mizo Idle" draggable={false} className="absolute bottom-0 w-full h-full object-contain object-bottom" animate={{ opacity: state === "idle" ? 1 : 0 }} transition={{ duration: 0.6 }} />
            <motion.img src={ASSETS.hover} alt="Mizo Ready" draggable={false} className="absolute bottom-0 w-full h-full object-contain object-bottom" animate={{ opacity: state === "hover" ? 1 : 0 }} transition={{ duration: 0.6 }} />
            <motion.img src={ASSETS.active} alt="Mizo Active" draggable={false} className="absolute bottom-0 w-full h-full object-contain object-bottom" animate={{ opacity: state === "holding" || state === "complete" ? 1 : 0 }} transition={{ duration: 0.35 }} />

            {/* الهالة البصرية الفخمة (Halo) */}
            <div
              className="absolute rounded-full pointer-events-none"
              style={{
                width: "320px", height: "320px", bottom: "10%",
                border: "1px solid rgba(255,255,255,0.04)",
                transform: `scale(${1 + progress * 0.04})`,
                opacity: progress * 0.5, transition: "transform 0.1s linear", backdropFilter: "blur(4px)",
              }}
            />
          </div>

          {/* 2. الحاوية السفلية للنصوص (40% من الشاشة) - ثابتة ومستحيل تنكسر */}
          <div className="w-full flex flex-col items-center justify-center text-center z-10" style={{ height: "40dvh", paddingBottom: "5vh" }}>
            
            <motion.div className="flex items-center justify-center gap-4" initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 1 }}>
              <span style={{ color: '#ffffff', fontWeight: 900, fontSize: 'clamp(2.5rem, 6vw, 4.5rem)', letterSpacing: '0.15em', lineHeight: 1 }}>MIZO</span>
              <span style={{ color: 'transparent', WebkitTextStroke: '2px rgba(255,255,255,0.8)', fontWeight: 900, fontSize: 'clamp(2.5rem, 6vw, 4.5rem)', letterSpacing: '0.15em', lineHeight: 1 }}>AMIN</span>
            </motion.div>

            <div className="flex items-center justify-center gap-4 mt-6 opacity-60 w-full">
              <span style={{ width: '40px', height: '1px', backgroundColor: 'rgba(255,255,255,0.4)' }}></span>
              <p style={{ color: 'white', letterSpacing: '0.5em', fontSize: 'clamp(9px, 2vw, 12px)', fontWeight: 'bold', textTransform: 'uppercase', margin: 0 }}>SPATIAL DIGITAL DOMAIN</p>
              <span style={{ width: '40px', height: '1px', backgroundColor: 'rgba(255,255,255,0.4)' }}></span>
            </div>

            <motion.p className="mt-8 text-[11px] tracking-[0.5em] uppercase text-white/40 h-4" initial={{ opacity: 0 }} animate={{ opacity: state !== "idle" ? 1 : 0 }} transition={{ duration: 0.4 }}>
              {state === "holding" ? "INITIALIZING NEURAL LINK..." : "HOLD / CLICK TO ENTER"}
            </motion.p>
          </div>

        </motion.div>
      )}
    </AnimatePresence>
  );
}
