"use client";

import { useState, Suspense } from "react";
import { Canvas } from "@react-three/fiber";
import { OrbitControls, Stars } from "@react-three/drei";
import * as THREE from "three";
import { useExperience } from "../engine/experienceStore";
import TheSolarSystem from "../components/3d/systems/TheSolarSystem";
import CinematicCameraController from "../components/3d/core/CinematicCameraController";
import ShootingStars from "../components/3d/effects/ShootingStars";
import IntroPortal from "../components/ui/IntroPortal";

export default function Home() {
  // حالة التحكم في الانتقال
  const [isIntroComplete, setIsIntroComplete] = useState(false);
  
  // حالات التحكم في الكواكب والكاميرا
  const activePlanet = useExperience((state) => state.activePlanet);
  const setActivePlanet = useExperience((state) => state.setPlanet);
  const [cameraFocus, setCameraFocus] = useState<THREE.Vector3 | null>(null);

  // الدالة التي يتم استدعاؤها بمجرد انتهاء التلاشي في IntroPortal
  const handleIntroIgnition = () => {
    setIsIntroComplete(true);
  };

  return (
    <main className="w-screen h-screen relative overflow-hidden bg-black">
      
      {/* ---------------- 1. الواجهة الأمامية (The Human Portal) ---------------- */}
      {!isIntroComplete && (
        <IntroPortal onEnter={handleIntroIgnition} />
      )}

      {/* ---------------- 2. عالم الـ 3D (The Spatial Engine) ---------------- */}
      {/* وضعنا absolute و z-0 لضمان بقاءه في الخلفية تحت الواجهة */}
      <div className="absolute inset-0 w-full h-full z-0">
        <Canvas
          shadows
          camera={{ position: [0, 20, 500], fov: 50 }}
          gl={{ antialias: true, toneMapping: THREE.ACESFilmicToneMapping }}
        >
          <color attach="background" args={["#000000"]} />
          <fog attach="fog" args={["#000000", 500, 2000]} />
          <ambientLight intensity={0.1} />

          <Suspense fallback={null}>
            {/* النجوم تعمل دائماً، بطيئة في البداية وتتسارع عند الدخول */}
            <Stars 
              radius={300} 
              depth={60} 
              count={5000} 
              factor={7} 
              saturation={0} 
              fade 
              speed={isIntroComplete ? 2 : 0.5} 
            />

            {/* 🛑 الحماية الهندسية: هذه العناصر لن يتم رسمها إطلاقاً حتى ينتهي الـ Intro */}
            {isIntroComplete && (
               <>
                 <ShootingStars />
                 
                 <TheSolarSystem
                   onPlanetFocus={(data) => {
                      setCameraFocus(data ? data.position : null);
                   }}
                 />
                 
                 <CinematicCameraController focusTarget={cameraFocus} />
               </>
            )}
          </Suspense>

          {/* تفعيل تحكم الماوس للمستخدم فقط بعد الدخول بنجاح */}
          {isIntroComplete && (
              <OrbitControls 
                makeDefault 
                enableDamping 
                dampingFactor={0.05} 
                minDistance={50} 
                maxDistance={800} 
              />
          )}
        </Canvas>
      </div>
      
    </main>
  );
}
